// 1. Single-line comment: Memulai kalkulasi sensor batch
/*
 * 2. Block comment:
 * Melakukan parsing JSON, null-safety, named function, map-filter-reduce,
 * switch-case, regex replace, dan format datetime.
 */
val rawInput = msg.payload?.rawData ?? "{\"speed\":100,\"temp\":95.5,\"batches\":[10,20,30]}"
val parsed = Json.parse(rawInput)

// 3. Null-safety & type conversion
val baseSpeed = (parsed?.speed ?? 0).toNumber()
val temperature = (parsed?.temp ?? 0).toNumber()

// 4. Named function
fun computeAdjustment(speed, temp) {
    val rounded = Math.round(temp)
    if (speed > 120) {
        return Math.max(rounded, 100)
    }
    return Math.min(rounded, 80)
}
val adjustment = computeAdjustment(baseSpeed, temperature)

// 5. Higher-order functions (map, filter, reduce) & Lambda
val batches = parsed?.batches ?? []
val doubledBatches = batches.map(fun (x) => x * 2)
val highBatches = doubledBatches.filter(fun (x) => x > 20)
val sumBatches = highBatches.reduce(fun (acc, x) => acc + x, 0)

// 6. Switch statement
var statusStr = "UNKNOWN"
switch (baseSpeed) {
    case 100:
        statusStr = "STABLE"
    case 150:
        statusStr = "PEAK"
    default:
        statusStr = "NORMAL"
}

// 7. Regex & string methods
val sensorName = parsed?.name ?? "  WO-105-A  "
val cleanedSensorName = sensorName.trim().toUpperCase()
val matches = cleanedSensorName.match("WO-\\d+")
var extractedWo = "NONE"
if (matches.length > 0) {
    extractedWo = matches[0]
}
val replacedSensorName = Regex.replace(cleanedSensorName, "-", "_")

// 8. DateTime
val executionTime = DateTime.now().toISOString()

// 9. Reassemble
msg.payload = {
    originalSpeed: baseSpeed,
    adjustment: adjustment,
    status: statusStr,
    totalBatchCount: batches.length,
    highBatchSum: sumBatches,
    extractedWorkOrder: extractedWo,
    formattedSensor: replacedSensorName,
    processedAt: executionTime
}
send(msg)

